import java.util.*;
import java.io.*;

public class C4 {
    public static void main(String[] args) throws IOException {
        Scanner sc = new Scanner(System.in);
        PrintWriter pw = new PrintWriter(System.out);
        int n = sc.nextInt();
        long[][] circles = new long[n][3];
        for (int i = 0; i < n; i++) {
            circles[i][0] = sc.nextLong();
            circles[i][1] = sc.nextLong();
            circles[i][2] = sc.nextLong();
        }
        List<double[]> points = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                double[] angles = crossSimple(circles[i][0], circles[i][1], circles[i][2], circles[j][0], circles[j][1], circles[j][2]);
                for (double angle : angles) {
                    points.add(new double[]{
                        circles[i][0] + circles[i][2] * Math.cos(angle),
                        circles[i][1] + circles[i][2] * Math.sin(angle)
                    });
                }
            }
        }
        double[][] ptsArray = points.toArray(new double[0][]);
        int pCount = ptsArray.length;
        boolean[] toRemove = new boolean[pCount];
        for (int i = 0; i < pCount; i++) {
            for (int j = i + 1; j < pCount; j++) {
                if (d2(ptsArray[i][0], ptsArray[i][1], ptsArray[j][0], ptsArray[j][1]) < 1e-12) {
                    toRemove[j] = true;
                }
            }
        }
        List<double[]> uniquePoints = new ArrayList<>();
        for (int i = 0; i < pCount; i++) {
            if (!toRemove[i]) {
                uniquePoints.add(ptsArray[i]);
            }
        }
        int totalPoints = uniquePoints.size();
        int totalEdges = 0;
        int components = 1;
        for (int i = 0; i < n; i++) {
            int countE = 0;
            for (double[] pt : uniquePoints) {
                if (Math.abs(d2(pt[0], pt[1], circles[i][0], circles[i][1]) - circles[i][2] * circles[i][2]) < 1e-12) {
                    countE++;
                }
            }
            if (countE == 0) components++;
            totalEdges += countE;
        }
        if (components > n) components = n;
        pw.println(totalEdges - totalPoints + components + 1);
        pw.flush();
    }

    public static double d2(double ax, double ay, double bx, double by) {
        return (bx - ax) * (bx - ax) + (by - ay) * (by - ay);
    }

    public static double[] crossSimple(long x, long y, long r, long tx, long ty, long tr) {
        long d2 = d2(x, y, tx, ty);
        if (d2 < (r - tr) * (r - tr) || d2 > (r + tr) * (r + tr)) return new double[0];
        double base = Math.atan2(ty - y, tx - x);
        double wing = Math.acos((d2 + r * r - tr * tr) / (2.0 * Math.sqrt(d2) * r));
        return new double[]{base - wing, base + wing};
    }
}
